-- elimina tabela de atributos e recria

if not exists(select name from sysobjects where name='TABCOMP' and type='U')
   begin
      create table TABCOMP(tabela varchar(128),atributo varchar(128),tipo varchar(128),precisao tinyint,escala tinyint)
   end
      else delete from TABCOMP

-- insere dados da tabela de atributos

                                                                                                                                                                                                                                                                 prec        scale
---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------- ------ ---- -----------



-- lista tabelas que não existem na base de dados local

select distinct tabela from TABCOMP
 where not exists(select 'ne' from sysobjects obj (nolock)
                   where (obj.name Like('TBS%') or obj.name Like('MSL%') or obj.name Like('TMP%')) and
                         obj.name = TABCOMP.tabela collate database_default)
 order by tabela

-- lista atributos não existentes

select 'alter table [' + rtrim(tabela) + '] add [' + rtrim(atributo) + '] ' + rtrim(tipo) + --'(' + rtrim(precisao) +
       case tipo
          when 'datetime' then ''
          when 'smallint' then ''
          when 'money' then ''
          when 'smallmoney' then ''
          when 'int' then ''
          when 'text' then ''
          else
             '(' + rtrim(precisao) +
             case
                when escala is null then ''
                else ',' + rtrim(escala)
             end
             + ')'
       end
       + ' default ' +
       case tipo
          when 'char'       then ''''''
          when 'datetime'   then '''17530101'''
          when 'decimal'    then '0'
          when 'int'        then '0'
          when 'money'      then '0'
          when 'smallint'   then '0'
          when 'smallmoney' then '0'
          when 'varchar'    then ''''''
          when 'text'       then ''''''
       else ''
       end + ' with values' +
       char(13) + 'go'
  from TABCOMP
 where not exists(select 'ne' from sysobjects obj (nolock) join syscolumns col (nolock) on col.id = obj.id
                                                           join systypes typ (nolock) on typ.xtype = col.xtype
                   where (obj.name Like('TBS%') or obj.name Like('MSL%') or obj.name Like('TMP%')) and
                         obj.name = TABCOMP.tabela collate database_default and col.name = TABCOMP.atributo collate database_default)
 order by tabela,atributo